head.script:
scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // widgetContainer 는 DIV 렌더로 기본 포커스 불가 -> tabIndex 부여
    let cList = $c.gcm.createCList({ tabIndex: "0" });

    // onclick/onfocus : 차단 여부 대비 확인용
    let eList = $c.gcm.createEList(["onclick", "onfocus"]);

    // comp 생성 함수 호출
    await $c.gcm.createBasicWidgetContainer(cList, eList);
}
